-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.rogue.dps.Name"] = "DPS in mischia"
L["rm.era.rogue.dps.Description"] = "Livelli 1–60, ogni specializzazione, anche sui reami Hardcore e Self-Found; costruita a partire da simulatore, Icy Veins e Wowhead. Dalla furtività: Premeditazione, Imboscata con un pugnale quando il bersaglio non ti è rivolto, Colpo Basso da solo, Garrota fuori dalle incursioni. In combattimento: Replica Immediata, Fendenti Furiosi da un punto combo quando manca su un'élite o su un bersaglio in salute (rinnovato a cinque punti nei suoi ultimi tre secondi), Smantella Armatura a cinque punti in gruppo quando hai Smantella Armatura Migliorata 2/2 e nessuno usa Incrinatura, uno Sventramento a due punti su un bersaglio in punto di morte, altrimenti Sventramento a cinque e nessuna abilità generatrice oltre i cinque. L'abilità generatrice segue ciò che conosci: Assalto Spettrale ed Emorragia fuori dalle incursioni, Pugnalata alle Spalle con un pugnale quando il bersaglio non ti è rivolto, altrimenti Assalto Funesto. Promemoria: veleni su ciascuna arma (Veleno Mortale sull'arma della mano secondaria se la porti), Calcio, Tè di Sboccialesto, Vortice di Lame e Scarica d'Adrenalina sulle élite o contro due nemici con Fendenti Furiosi attivo, Sangue Freddo a cinque, Evasione da solo quando sei ferito. Sparizione, Sfregio Oculare, Preparazione, Colpo ai Reni e abilità razziali sono elencate ma disattivate; Finta, Scatto, Accecamento, Tramortimento e posizionamento restano a te."
L["rm.era.rogue.dps.simulator.Name"] = "Spade, Assalto Funesto sincronizzato con i colpi (simulatore)"
L["rm.era.rogue.dps.simulator.Description"] = "L'ordine Combattimento \"sudato\" di simulatore per Specializzazione nelle Spade, un'alternativa alla rotazione integrata consigliata di DPS in mischia, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Assalto Funesto solo subito dopo un colpo della mano primaria (2,0 secondi o più al successivo, impostato per una spada di velocità 2,6–2,8; cambialo in un duplicato), a meno che l'energia non sia quasi piena o il bersaglio stia per morire, così che l'attacco extra della spada non ritardi il tuo colpo. Anche Sventramento a cinque aspetta Fendenti Furiosi, l'energia piena o un bersaglio in punto di morte. Per il resto come la rotazione integrata consigliata."
L["rm.era.rogue.dps.warcrafttavern.Name"] = "DPS in mischia, mosse finali a cinque punti (Warcraft Tavern)"
L["rm.era.rogue.dps.warcrafttavern.Description"] = "Il metodo di Warcraft Tavern, un'alternativa alla rotazione integrata consigliata di DPS in mischia, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Ogni mossa finale aspetta cinque punti combo così che Affondi Implacabili la rimborsi. Fendenti Furiosi viene usato dal suo secondo grado (livello 42) quando manca o sta per finire, altrimenti Sventramento; niente Fendenti Furiosi a pochi punti, niente Sventramento in punto di morte e niente Smantella Armatura (ci pensa l'Incrinatura di un guerriero). Stesse aperture, abilità generatrici e promemoria della rotazione integrata consigliata."
L["rm.forever.rogue.dps.Name"] = "DPS in mischia"
L["rm.forever.rogue.dps.Description"] = "Danni in mischia per ogni specializzazione del Ladro dal livello 1 al 60, costruita a partire da Icy Veins, Wowhead e Warcraft Tavern. Il generatore di punti segue ciò che conosci: Mutilazione (Assalto Funesto per il quinto punto), Emorragia, Pugnalata alle Spalle quando il bersaglio non ti è rivolto, altrimenti Assalto Funesto. Dalla Furtività apre con Premeditazione, Colpo Basso da solo, Garrota per Scaltrezza sulle élite in gruppo, altrimenti Imboscata o Garrota. Mantiene attivi Fendenti Furiosi e Tossina, usa Esponi Armatura in gruppo sulle élite quando nessun guerriero ha applicato cinque Spaccarmatura, poi spende cinque punti in Perforazione (Scaltrezza, combattimenti lunghi) o Eliminazione, e non accumula mai oltre cinque. Promemoria: veleni su ogni arma, Calcio, Vortice di Lame e Scarica d'Adrenalina contro gruppi ed élite, Sangue Freddo, Evasione, Finta, Tè di Cardo e Preparazione. Restano a te: Sparizione, Scatto, Colpo ai Reni, Accecamento, Tramortimento e il posizionamento. Forever limita i dati di combattimento, quindi Rotation Master elenca questa rotazione integrata a titolo di riferimento e per ora non la seleziona automaticamente."
L["rm.forever.rogue.subtlety.warcrafttavern.Name"] = "Scaltrezza, build Imboscata (Warcraft Tavern)"
L["rm.forever.rogue.subtlety.warcrafttavern.Description"] = "La build Scaltrezza Imboscata/Tagliagole di Warcraft Tavern: Premeditazione e Imboscata a ogni apertura, di nuovo Imboscata ogni volta che Tagliagole lo consente, Pugnalata alle Spalle da dietro come generatore (Emorragia quando il bersaglio ti è rivolto), Colpo Spettrale appena pronto, e Fendenti Furiosi poi Eliminazione a cinque punti, senza Perforazione. Ti ricorda di usare Sparizione per un'altra Imboscata su un boss tenuto da un difensore. Sceglila al posto della rotazione integrata consigliata per il Ladro se hai preso i talenti Tagliagole; si applica con Scaltrezza come albero dei talenti principale e Tagliagole nei talenti. Stessi promemoria per veleni e tempi di recupero della rotazione integrata consigliata. Un'alternativa alla rotazione integrata consigliata DPS del Ladro, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.forever.rogue.subtlety.wowhead.Name"] = "Scaltrezza, build Garrota (Wowhead)"
L["rm.forever.rogue.subtlety.wowhead.Description"] = "La Scaltrezza di Wowhead: Premeditazione e Garrota a ogni apertura, e Sparizione (poi Preparazione) usata nella rotazione per riaprire con Garrota una volta scaduta la precedente. Fendenti Furiosi sempre attivo, Esponi Armatura in gruppo, Perforazione come mossa finale a cinque punti, Emorragia come unico generatore. Questa variante spende Sparizione, la tua via di fuga, per i danni: sceglila consapevolmente. Si applica con Scaltrezza come albero dei talenti principale, Dirty Deeds nei talenti e Premeditazione appresa. Stessi promemoria per veleni e tempi di recupero della rotazione integrata consigliata. Un'alternativa alla rotazione integrata consigliata DPS del Ladro, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
L["rm.mop.rogue.assassination.Name"] = "Consigliata"
L["rm.mop.rogue.assassination.Description"] = "Consigliata per Assassinio, dal livello 10 al 90 (simulatore e Wowhead per la Fase 5, con i passaggi di livellamento di Icy Veins). Apre dalla furtività con Colpo Basso quando giochi da solo, altrimenti Mutilazione (Eliminazione con Lato Cieco, con un pugnale). Mantiene attivi Fendenti Furiosi (Affondo Venefico lo rinnova dal livello 60) e Perforazione sul bersaglio, spende cinque punti in Affondo Venefico finché dura Perforazione e quattro punti per mantenere attivo l'effetto benefico di Affondo Venefico quando non hai Anticipazione, poi Marchio della Morte, Eliminazione sotto il 35% o con Lato Cieco (richiede un pugnale nella mano primaria), e Mutilazione. Contro quattro o più nemici che ti combattono: Fendenti Furiosi, Tempesta Cremisi a sette nemici, Perforazione, Affondo Venefico e Ventaglio di Lame; spostare Perforazione su altri bersagli con Tab spetta a te. Da solo aggiunge Recupero Vitale e un Colpo ai Reni quando sei in difficoltà. Promemoria: veleni, Calcio, Ritorsione nei combattimenti lunghi, Lame d'Ombra con Ritorsione, Sparizione e Preparazione durante Ritorsione, Passo nell'Ombra dalla distanza, Evasione da solo. Lasciati a te: Trucchi del Mestiere e Smantella Armatura (elencati ma disattivati), Finta, Scatto e posizionamento."
L["rm.mop.rogue.assassination.icyveins.Name"] = "Affondo Venefico a cinque (Icy Veins)"
L["rm.mop.rogue.assassination.icyveins.Description"] = "Disattivata per impostazione predefinita. L'ordine di Icy Veins e Method: Sparizione appena pronta per una Mutilazione dalla furtività, Ritorsione appena pronta quando il combattimento è abbastanza lungo, Affondo Venefico solo a cinque punti, Perforazione sempre attiva, Eliminazione sotto il 35% o con Lato Cieco, Mutilazione. Da quattro a otto nemici: Ventaglio di Lame con Perforazione a tre punti o più; nove o più: solo Ventaglio di Lame e Affondo Venefico. La rotazione integrata Assassinio consigliata segue invece i consigli più recenti della Fase 5; per usare questa, attivala e disattiva quella consigliata."
L["rm.mop.rogue.combat.Name"] = "Consigliata"
L["rm.mop.rogue.combat.Description"] = "Consigliata per Combattimento, dal livello 10 al 90 (Wowhead e simulatore per la Fase 5). Dalla patch dell'Assedio di Orgrimmar Assalto Funesto costa 50 di energia, quindi Assalto Rivelatore è l'abilità generatrice e Assalto Funesto viene usato solo durante Brama di Sangue o Eroismo con Scarica d'Adrenalina (e prima del livello 20). Apre con Colpo Basso da solo, altrimenti Imboscata. Mantiene attivi Fendenti Furiosi da due punti e Assalto Rivelatore sul bersaglio, spende cinque punti solo mentre Assalto Rivelatore è attivo (Fendenti Furiosi, Perforazione in un lungo combattimento contro un solo bersaglio senza Vortice di Lame, Sventramento) e a cinque aspetta l'energia. Contro otto o più nemici: Fendenti Furiosi, Tempesta Cremisi e Ventaglio di Lame. Da solo aggiunge Recupero Vitale e Colpo ai Reni. Promemoria: veleni, Calcio, Vortice di Lame attivato contro due o più nemici e poi di nuovo disattivato, Scarica d'Adrenalina con poca energia insieme a Lame d'Ombra, Furia Omicida, Sparizione e Preparazione per Imboscata durante Consapevolezza Profonda, Passo nell'Ombra, Evasione da solo. Lasciati a te: Trucchi del Mestiere e Smantella Armatura (elencati ma disattivati), Finta e il posizionamento dietro al bersaglio per Imboscata."
L["rm.mop.rogue.combat.hekili.Name"] = "Anticipazione (Hekili)"
L["rm.mop.rogue.combat.hekili.Description"] = "Disattivata per impostazione predefinita. L'ordine MoP di Hekili per Combattimento con Anticipazione: Assalto Rivelatore è l'unica abilità generatrice, anche durante Brama di Sangue; le mosse finali aspettano Consapevolezza Profonda, quattro cariche di Anticipazione o il ritorno di Lame d'Ombra, poi Fendenti Furiosi, Perforazione su uno o due bersagli longevi, Tempesta Cremisi a sette nemici e Sventramento; Fendenti Furiosi viene rinnovato in anticipo a 11 cumuli di Astuzia del Bandito; Ventaglio di Lame da quattro nemici. Si applica solo con il talento Anticipazione. Per usarla attivala e disattiva la rotazione integrata Combattimento consigliata."
L["rm.mop.rogue.combat.icyveins.Name"] = "Assalto Funesto come generatore (Icy Veins)"
L["rm.mop.rogue.combat.icyveins.Description"] = "Disattivata per impostazione predefinita, e superata per la Fase 5. L'ordine di Icy Veins, Warcraft Tavern, Method e wowtbc.gg di prima della patch dell'Assedio di Orgrimmar: Fendenti Furiosi, Assalto Rivelatore sempre attivo, Perforazione a cinque punti in un lungo combattimento contro un solo bersaglio e Sventramento, con Assalto Funesto come abilità generatrice. Stessi promemoria e gestione dei gruppi della rotazione integrata Combattimento consigliata. Sceglila solo se segui quelle guide; attivala e disattiva quella consigliata."
L["rm.mop.rogue.subtlety.Name"] = "Consigliata"
L["rm.mop.rogue.subtlety.Description"] = "Consigliata per Scaltrezza con Concentrazione dell'Ombra, dal livello 10 al 90 (simulatore e Wowhead per la Fase 5). In furtività o durante Danza dell'Ombra: Premeditazione, Fendenti Furiosi prima dell'ingaggio, mosse finali a cinque punti, Imboscata, Garrota. Fuori: Fendenti Furiosi; a cinque punti Fendenti Furiosi e Perforazione quando stanno per scadere, Sventramento finché durano entrambi; Marchio della Morte; Emorragia per mantenerne il sanguinamento; Pugnalata alle Spalle (con un pugnale) quando il bersaglio non ti sta attaccando, altrimenti Emorragia. Contro tre o più nemici: Fendenti Furiosi, Tempesta Cremisi, Sventramento e Ventaglio di Lame. Da solo aggiunge Recupero Vitale e Colpo ai Reni. Promemoria: veleni, Calcio, Danza dell'Ombra a 75 di energia con Fendenti Furiosi e Perforazione attivi, Sparizione quando Individuazione Debolezze sta per finire, Preparazione, Lame d'Ombra fuori da Danza e furtività, Passo nell'Ombra, Evasione da solo. Lasciati a te: stare dietro al bersaglio (RM non può vedere l'orientamento), Trucchi del Mestiere e Smantella Armatura (elencati ma disattivati)."
L["rm.mop.rogue.subtlety.warcrafttavern.Name"] = "Sotterfugio (Warcraft Tavern)"
L["rm.mop.rogue.subtlety.warcrafttavern.Description"] = "Scelta automaticamente al posto della rotazione integrata con Concentrazione dell'Ombra quando il tuo talento di primo livello è Sotterfugio (la build di Warcraft Tavern). Premeditazione e Fendenti Furiosi prima dell'ingaggio; in furtività, durante Danza dell'Ombra o nella persistenza di Sotterfugio, mosse finali a cinque punti e poi Imboscata ogni volta che va a segno. Due o tre nemici: mantieni attiva Perforazione e spendi cinque punti in Tempesta Cremisi invece di Sventramento; quattro o più aggiungono Ventaglio di Lame. Un bersaglio: Fendenti Furiosi, Perforazione, Sventramento, Emorragia per il suo sanguinamento, Pugnalata alle Spalle da dietro con un pugnale, altrimenti Emorragia. Danza dell'Ombra e Sparizione sono promemoria a 60 di energia con Fendenti Furiosi attivo; sincronizzarle con i proc dei monili, come suggerisce Tavern, spetta a te."
L["rm.mop.rogue.unspecialized.Name"] = "Senza specializzazione"
L["rm.mop.rogue.unspecialized.Description"] = "Per i livelli da 1 a 9, o per un ladro che non ha ancora scelto una specializzazione; la rotazione integrata di ciascuna specializzazione subentra appena ne scegli una. Apre dalla furtività con Colpo Basso quando giochi da solo, Imboscata o Assalto Funesto; suggerisce Furtività fuori dal combattimento; Fendenti Furiosi da due punti, Recupero Vitale e Colpo ai Reni quando sei da solo e ferito, Sventramento a quattro punti (due quando il bersaglio sta per morire), Assalto Funesto. Promemoria: veleni una volta appresi, Calcio, Evasione da solo."
L["rm.retail.rogue.assassination.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.rogue.assassination.Description"] = "Consigliata per Assassinio in Midnight. In combattimento il gioco ora nasconde agli addon i tuoi sanguinamenti, gli effetti benefici, l'energia, i tempi di recupero e la salute, quindi questa rotazione mostra il suggerimento stesso dell'Assistente di Combattimento di Blizzard (la rotazione a un pulsante, che gestisce l'apertura dalla furtività, Garrota, Perforazione, Affondo Venefico, Stigma Letale e Rovina dei Re), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: un veleno letale e uno non letale e Furtività tra un ingaggio e l'altro, Sparizione quando sei fuori dalla furtività in combattimento, Calcio su un lancio interrompibile (si illumina solo dove il gioco permette di leggere il lancio). La salute è nascosta su Retail, quindi Fiala Cremisi spetta a te."
L["rm.retail.rogue.assassination.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.rogue.assassination.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft mantiene i sanguinamenti in base ai loro timer, che Midnight nasconde in combattimento; l'energia è nascosta su Retail, quindi l'accumulo di energia è escluso. Dalla furtività Garrota, poi Imboscata. Garrota nell'ultimo 30% della sua durata quando non hai il massimo dei punti combo, Perforazione a 5+ punti nell'ultimo 30% della sua durata; a 5+ punti combo Colpo di Grazia o Affondo Venefico; sotto, Tempesta Cremisi contro tre o più nemici, Ventaglio di Lame contro due o più nemici vicini, Imboscata, Mutilazione. Promemoria: Stigma Letale con entrambi i sanguinamenti attivi, Rovina dei Re insieme a esso, Sparizione con Stigma Letale pronto, Stilettata su un bersaglio con Marchio dell'Inseguitore della Morte, Tè di Sboccialesto ogni volta che è pronto in combattimento, più i promemoria comuni di veleni, Furtività e Calcio."
L["rm.retail.rogue.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.rogue.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Ladro). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Ladro condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.rogue.outlaw.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.rogue.outlaw.Description"] = "Consigliata per Fuorilegge in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard (gestisce l'apertura dalla furtività, Roulette Assassina, Vortice di Lame, Scarica d'Adrenalina, In Mezzo agli Occhi e le mosse finali), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: veleni e Furtività tra un ingaggio e l'altro, Sparizione quando sei fuori dalla furtività in combattimento, Calcio. La salute è nascosta su Retail, quindi Fiala Cremisi spetta a te. Roulette Eterna resta a te: il gioco nasconde quanti effetti benefici di Roulette Assassina hai."
L["rm.retail.rogue.outlaw.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.rogue.outlaw.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins, SimulationCraft e Wowhead legge gli effetti benefici di Roulette Assassina, i cumuli di Opportunità e l'energia, che Midnight nasconde in combattimento. Dalla furtività Imboscata. A un punto combo dal massimo o più: In Mezzo agli Occhi, Furia Omicida, Colpo di Grazia, Eliminazione. Altrimenti Imboscata con Audacia, Colpo di Pistola a sei cumuli di Opportunità (tre con pochi punti combo), Imboscata, Assalto Funesto. Promemoria: Roulette Assassina senza alcun tiro attivo, Scarica d'Adrenalina a due punti combo o meno, Vortice di Lame mantenuto contro due o più nemici, Scatto Tagliente, Preparazione quando Scarica d'Adrenalina, In Mezzo agli Occhi e Scatto Tagliente sono tutti in recupero. Roulette Eterna resta manuale."
L["rm.retail.rogue.subtlety.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.rogue.subtlety.Description"] = "Consigliata per Scaltrezza in Midnight. Mostra il suggerimento dell'Assistente di Combattimento di Blizzard (gestisce l'apertura dalla furtività, Lame d'Ombra, Morso di Faucinere, Danza dell'Ombra, Tecnica Segreta e le mosse finali), e si ferma mentre lanci o quando non hai un nemico come bersaglio. Promemoria per ciò che tralascia: veleni e Furtività tra un ingaggio e l'altro, Calcio su un lancio interrompibile. La salute è nascosta su Retail, quindi Fiala Cremisi spetta a te."
L["rm.retail.rogue.subtlety.icyveins.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.rogue.subtlety.icyveins.Description"] = "Solo riferimento, disattivata per impostazione predefinita: l'ordine di Icy Veins e SimulationCraft riserva Danza dell'Ombra a Tecnica Segreta e legge Danza dell'Ombra, Notte Cupa e l'energia, che Midnight nasconde in combattimento. In furtività prima dell'ingaggio: Assalto d'Ombra. A un punto combo dal massimo o più: Sventramento con Notte Cupa, Tecnica Segreta durante Danza dell'Ombra, Colpo di Grazia, Polvere Nera contro tre o più nemici, Sventramento. Altrimenti Assalto d'Ombra, Tempesta di Shuriken contro due o più, Lama Tenebrosa o Pugnalata alle Spalle. Promemoria: Morso di Faucinere durante Danza dell'Ombra, Lame d'Ombra con Danza dell'Ombra pronta, Danza dell'Ombra a due punti combo o meno (o sei o più) quando Tecnica Segreta è pronta o Lame d'Ombra è attiva, Sparizione fuori dalla furtività a due punti combo o meno."
L["rm.sod.rogue.dps.Name"] = "DPS in mischia (SoD)"
L["rm.sod.rogue.dps.Description"] = "Season of Discovery, livelli 1–60 con le rune man mano che le incidi; costruita a partire da simulatore Fase 6, Icy Veins e Zockify Fase 8. Dalla furtività: Assalto d'Ombra, Garrota in gruppo, Imboscata per una build con Pugnalata alle Spalle con un pugnale, Colpo Basso da solo. Contro tre o più nemici che ti combattono: prima Schioppo, Tempesta Cremisi, Ventaglio di Lame. Poi Imboscata con un proc di Tagliagole (con un pugnale), Fendente di Sciabola mantenuto a tre cumuli, Coltello Avvelenato a quattro cumuli di veleno, Fendenti Furiosi da due punti (rinnovato da quattro, a meno che non sia inciso Cut to the Chase), il compito di Smantella Armatura quando nessuno usa Incrinatura né mantiene attivo Veleno Sebaceo, con Carneficina inciso un sanguinamento (Tempesta Cremisi, altrimenti Perforazione; nessuno con Fendente di Sciabola), Affondo Venefico a cinque (Sventramento finché non lo incidi), e un'abilità generatrice in base alla runa dei guanti: Mutilazione, Fendente di Sciabola, Pugnalata alle Spalle (con un pugnale), altrimenti Assalto Funesto. Promemoria: un incantamento temporaneo su ciascuna arma, Calcio, Tè di Sboccialesto, Vortice di Lame, Scarica d'Adrenalina, Sangue Freddo ed Evasione, e con Maestro di Scaltrezza inciso Sparizione per rinnovarlo e Preparazione."
L["rm.sod.rogue.dps.icyveins.Name"] = "DPS in mischia, Perforazione per Carneficina (SoD, Icy Veins)"
L["rm.sod.rogue.dps.icyveins.Description"] = "L'ordine della Season of Discovery di Icy Veins, un'alternativa alla rotazione integrata consigliata di DPS in mischia della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Ogni mossa finale a cinque punti combo, prima Fendenti Furiosi quando manca o sta per finire, poi Perforazione mantenuta con Carneficina inciso, poi Affondo Venefico; Coltello Avvelenato solo a cinque cumuli di veleno; Schioppo o Ventaglio di Lame contro tre nemici. Stesse aperture, abilità generatrici e promemoria della rotazione integrata consigliata; il compito di Veleno Sebaceo resta a te."
L["rm.sod.rogue.dps.zockify.Name"] = "DPS in mischia, Affondo Venefico essenziale (SoD, Zockify)"
L["rm.sod.rogue.dps.zockify.Description"] = "La lista essenziale della Season of Discovery di Zockify, un'alternativa alla rotazione integrata consigliata di DPS in mischia della Season of Discovery, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Niente sanguinamenti e niente Smantella Armatura. Coltello Avvelenato a quattro cumuli di veleno, Fendenti Furiosi quando manca (da due punti, quattro con Fendente di Sciabola), Affondo Venefico a cinque, poi l'abilità generatrice della runa dei guanti. La raffica di Sparizione e Sangue Freddo resta a te."
L["rm.sod.rogue.tank.Name"] = "Difensore (SoD)"
L["rm.sod.rogue.tank.Description"] = "Difensore della Season of Discovery, scelto quando è inciso Solo una Ferita Superficiale; costruita a partire da simulatore Fase 6, Icy Veins, Zockify e Warcraft Tavern. Replica Immediata, Doppio Attacco appena pronto, Lame Danzanti da un punto combo (rinnovata da tre), Fendenti Furiosi da tre (rinnovato da quattro), Ventaglio di Lame, Tempesta Cremisi e Schioppo contro tre o più nemici, Schioppo mentre Lame Danzanti è attiva, Sventramento a cinque con entrambi gli effetti benefici attivi, Coltello Avvelenato con poca energia, poi Fendente di Sciabola, Mutilazione o Assalto Funesto. Promemoria: Beffa in gruppo quando il tuo bersaglio attacca qualcun altro, Calcio, Evasione sotto metà della salute, Vortice di Lame, Scarica d'Adrenalina, Tè di Sboccialesto e veleni per le armi (quello della mano secondaria solo con un'arma nella mano secondaria). Passo nell'Ombra e il compito di Veleno Sebaceo restano a te."
L["rm.tbc.rogue.dps.simulator.Name"] = "DPS in mischia (simulatore)"
L["rm.tbc.rogue.dps.simulator.Description"] = "Livelli 1–70, ogni specializzazione. Dalla furtività: Premeditazione, poi Colpo Basso da solo o Garrota in gruppo, altrimenti Imboscata (con un pugnale nella mano principale). In combattimento: Risposta, Fendenti Furiosi da due punti combo (rinnovato negli ultimi due secondi), Eliminazione su un bersaglio in punto di morte, e a cinque punti Perforazione quando durerà (non mentre Vortice di Lame colpisce più bersagli), altrimenti Eliminazione. Accumula punti con Mutilazione o Pugnalata alle Spalle (pugnale) quando il bersaglio non ti attacca, altrimenti con Emorragia o Assalto Funesto. Ti ricorda i veleni mancanti, Calcio, Vortice di Lame e Scarica d'Adrenalina, Sangue Freddo ed Evasione. Esponi Armatura, Colpo ai Reni, Finta, Sparizione e il posizionamento restano a te."
L["rm.tbc.rogue.dps.wowhead.Name"] = "DPS in mischia (Wowhead)"
L["rm.tbc.rogue.dps.wowhead.Description"] = "Livelli 1–70, ogni specializzazione, seguendo Wowhead. Stesse aperture dalla furtività, generatori di punti e promemoria della versione simulatore, ma Fendenti Furiosi parte da un punto combo e ogni mossa finale a cinque punti è Eliminazione: niente Perforazione. Esponi Armatura, Colpo ai Reni, Finta, Sparizione e il posizionamento restano a te. Un'alternativa alla rotazione integrata consigliata DPS in mischia di simulatore, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità."
